                if last_end[p] is not None:
                    reds[p].append(tt[k] - last_end[p])
            last_end[p] = tt[k]
    print("ctrl", S["controller_names"][c])
    for p in range(4):
        r = np.array(reds[p])
        print(f"  phase {p}: n={len(r)} red mean {r.mean():.1f} q90 {np.quantile(r,0.9):.0f} q99 {np.quantile(r,0.99):.0f} max {r.max():.0f}")
